WORDS={'0234': '06035300000355', '0235': '05035403550240', '0236': '06035400000355', '0237': '01035300000354', '0240': '01035400000356'};SHA={'examples/historical/gy1962/au1_absolute_predivision_0234_0240.k41': 'e404f0c4d7ae4133e8f02c240822c16f067b987084999acf7558caef872fe23d', 'examples/historical/gy1962/au1_absolute_predivision_0234_0240_provenance.tsv': 'dad7042adbd3d4fdb9e3c9b99bf012037a5a7ab962c3a8561807fa1659b9bc2f', 'docs/ISA_07_D15B1_H21_ABSOLUTE_PREDIVISION_BRANCH.md': '608f6a2f9ebfada8376bc3bd015bf94d273b846938bd24f214e144bba9419b40', 'docs/ISA_07_D15B1_H21_DECISION_LEDGER.tsv': 'bf7bd1a53378b410ffb7ae566f77b4d081f6a18f8693acf0a52b1972f6efbb2f'};README_SHA='e37d0b4f2dd8723b95926a959f54bb94892c1e9987918dd051c2bdd3e5bcd9f3';APPEND='\n## AU test I, absolute-value pre-division branch 0234–0240 (D15/B1-H21)\n\n- `au1_absolute_predivision_0234_0240.k41` transcribes five\n  historical instruction words from GY1962 printed p.174: opcode 06\n  absolute-magnitude subtraction, opcode 05 magnitude comparison,\n  and opcode 01 signed addition. Control may skip `0236–0237`.\n- Entry `0234`, branch `0235`: when `|RAM[0354]| <= |RAM[0355]|`,\n  jump directly to `0240`; otherwise execute `0236`, `0237`, then\n  `0240`. Constrain each native probe to 3 or 5 instructions and\n  stop **before** executing `0241` (outside this qualified fragment).\n- Scratch values `0353–0356` have no independently established\n  historical entry state. SOURCE_ZERO_INIT is host-initialized RAM,\n  not a source-seeded historical oracle. Three labeled PRIVATE seeds\n  exercise both comparison outcomes, including negative operand signs.\n  Results compare against an exact sign-magnitude HOST model; signed-zero\n  alternatives and prior H11 remain OPEN, not inferred as historical ISA.\n- H19_SEED=UNKNOWN; H20_SCRATCH=UNKNOWN; earlier H9/H10/H11/H13/H14/H17\n  conflicts OPEN_UNCHANGED; no CPU, ROM, prior-image mutation and\n  HARDWARE_ORACLE=0.\n\n```sh\ng++ -std=c++17 -O0 -Iinc src/main.cpp src/asm_disasm.cpp -o tempkyiv/d15b1h21_kyivemu.exe\npython -B tools/isa07_d15b1_h21_native.py --cli-exe tempkyiv/d15b1h21_kyivemu.exe --timeout 20\n```\n'
def git(*args):return subprocess.check_output(['git',*args],stderr=subprocess.PIPE).decode().rstrip('\n')
def norm(b):
 assert b'\r' not in b.replace(b'\r\n',b'\n'),'STRAY_CR'
 return b.replace(b'\r\n',b'\n')
def recs(b):
 a=[line.split() for line in b.decode('ascii').splitlines() if re.fullmatch(r'[0-7]{4} [0-7]{14}',line)]
 assert len(a)==5 and len(set(x[0] for x in a))==5,'SOURCE_COUNT_OR_DUP'
 return dict(a)
def selftest():
 assert len(PINS)==68 and all(re.fullmatch('[0-9a-f]{40}',v) for v in PINS.values()),'GIT_PIN_WIDTH'
 assert len(WORDS)==5 and len(NEW)==6 and len(SHA)==4,'SHAPE'
 assert recs(('KYIV41-OCT1\n'+'\n'.join(a+' '+w for a,w in WORDS.items())+'\n').encode())==WORDS
 assert WORDS['0234']=='06035300000355' and WORDS['0235']=='05035403550240','FIRST_PAIR'
 assert WORDS['0236']=='06035400000355' and WORDS['0237']=='01035300000354' and WORDS['0240']=='01035400000356','SECOND_PATH'
 assert all(a not in WORDS for a in ['0241','0353','0354','0355','0356']),'UNPRINTED_SEED_OR_BOUNDARY'
 assert WORDS['0235'] != '05035403550241' and WORDS['0236'] != '06035300000355','MUTANTS_REJECTED'
 assert norm(('\r\n'.join(['a','b'])+'\r\n').encode())==b'a\nb\n','CRLF'
 print('D15B1H21-AUDIT-SELFTEST PASS WORDS=5/5 MUTANTS_REJECTED=1 CRLF=1 GIT_PIN_WIDTH=68/68 BRANCH_TRUE_FALSE=1 BOUNDARY_0241=1')
def audit():
 root=pathlib.Path(__file__).resolve().parent.parent
 assert git('rev-parse','HEAD')==BASE,'BASELINE'
 assert git('branch','--show-current')=='main' and not git('rev-parse','--show-prefix'),'ROOT_OR_BRANCH'
 want={' M '+README}|{'?? '+x for x in NEW}
 got=set(git('status','--porcelain=v1','--untracked-files=all').splitlines())
 assert got==want,('SCOPE',sorted(got),sorted(want))
 for p,s in PINS.items():assert git('rev-parse','HEAD:'+p)==s,('GIT_PIN',p)
 readme=norm((root/README).read_bytes())
 assert hashlib.sha256(readme).hexdigest()==README_SHA and readme.endswith(APPEND.encode()),'README_SHA_APPEND'
 for p,s in SHA.items():assert hashlib.sha256(norm((root/p).read_bytes())).hexdigest()==s,('CONTENT_SHA',p)
 assert recs((root/IMAGE).read_bytes())==WORDS,'WORD_TRANSCRIPTION'
 lines=norm((root/PROV).read_bytes()).decode('ascii').splitlines()
 assert len(lines)==6 and lines[0]=='address\tcode_octal_14\tprinted_page\trole\tverification','PROV_HEADER'
 for row in lines[1:]:
  a=row.split('\t');assert len(a)==5 and WORDS[a[0]]==a[1] and a[2]=='174' and a[4]=='VISUAL_FIRST_PASS',('PROV',a)
 print('D15B1H21-AUDIT PASS BASELINE='+BASE[:7]+' MOD=1/1 NEW=6/6 WORDS=5/5 PROGRAM=5 DATA=0 SOURCE_PINS=68/68 CONTENT_SHA=4/4 HISTORICAL_SEED=UNKNOWN TRUE_FALSE_PATHS=2/2 BOUNDARY_0241_NOT_EXECUTED=1 H19_SEED=UNKNOWN H20_SCRATCH=UNKNOWN H9_H10_H11_H13_H14_H17_CONFLICTS=OPEN_UNCHANGED CPU_MUTATION=0 ROM_IMMUTABLE=1 PRIOR_IMAGES_IMMUTABLE=1 NATIVE_GATE=PENDING HARDWARE_ORACLE=0')
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--self-test',action='store_true');args=a.parse_args()
 try:selftest();None if args.self_test else audit()
 except BaseException as e:raise SystemExit('D15B1H21-AUDIT FAIL '+repr(e))
